DROP TABLE IF EXISTS gv_plv; CREATE TABLE gv_plv ( sequence smallint  NULL, country smallint  NULL, plot integer  NULL, sample_id smallint  NULL, team_id integer  NULL, no_members smallint  NULL, survey_type smallint  NULL, survey_nr smallint  NULL, date_sampling date  NULL, latitude character varying(7)  NULL, longitude character varying(7)  NULL, altitude smallint  NULL, fence smallint  NULL, sampled_area smallint  NULL, tree_cover smallint  NULL, shrub_height numeric  NULL, shrub_cover numeric  NULL, shrub_low_cover numeric  NULL, shrub_high_cover numeric  NULL, herb_height numeric  NULL, herb_cover numeric  NULL, mosses_cover numeric  NULL, bare_soil_cover numeric  NULL, litter_cover numeric  NULL, other_observations character varying  NULL);
